// Module: TX
// Description: UART 发送模块，实现起始位+8bit数据位+停止位串行发送，支持可配置波特率
// Auto-generated by WriteRTL Agent

module TX (
    input logic        clk,
    input logic        rst_n,
    input logic [7:0] tx_data,
    input logic        tx_start,
    input logic [15:0] baud_div,
    output logic        tx_busy,
    output logic        tx_done,
    output logic        tx
);

    // ── 寄存器 ──
    logic [7:0] tx_data_reg = 8'd0;

    // ── UART 发送状态机 ──
    logic [3:0] tx_bit_cnt;
    logic [9:0] tx_shift_reg;  // start + 8 data + stop
    typedef enum logic [1:0] {TX_IDLE, TX_START, TX_DATA, TX_STOP} tx_state_t;
    tx_state_t tx_state;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_state <= TX_IDLE;
            tx <= 1'b1;
            tx_busy <= 1'b0;
            tx_bit_cnt <= '0;
        end else begin
            case (tx_state)
                TX_IDLE: if (tx_start) begin
                    tx_shift_reg <= {1'b0, tx_data, 1'b1};
                    tx_busy <= 1'b1;
                    tx_state <= TX_DATA;
                    tx_bit_cnt <= '0;
                    tx <= 1'b0;  // start bit
                end
                TX_DATA: begin
                    tx <= tx_shift_reg[0];
                    tx_shift_reg <= tx_shift_reg >> 1;
                    if (tx_bit_cnt == 4'd9)
                        tx_state <= TX_STOP;
                    else
                        tx_bit_cnt <= tx_bit_cnt + 1;
                end
                TX_STOP: begin
                    tx <= 1'b1;
                    tx_busy <= 1'b0;
                    tx_state <= TX_IDLE;
                end
            endcase
        end
    end

endmodule